import React, { useEffect, useState } from "react";
import { useLocation, Link } from "react-router-dom";
import ProductList from "../common/ProductList";
import Pagination from "../common/Pagination";
import ApiService from "../../service/ApiService";
import { FaArrowRight, FaShoppingBag } from "react-icons/fa";
import "../../style/home.css";

const Home = () => {
    const location = useLocation();
    const [products, setProducts] = useState([]);
    const [featuredProducts, setFeaturedProducts] = useState([]);
    const [currentPage, setCurrentPage] = useState(1);
    const [totalPages, setTotalPages] = useState(0);
    const [error, setError] = useState(null);
    const itemsPerPage = 10;

    const categories = [
        { id: 1, name: "Computers", imageUrl: "/images/categories/computer.jpg" },
        { id: 2, name: "Mobile", imageUrl: "/images/categories/mobile.jpg" },
        { id: 3, name: "Drones & Cameras", imageUrl: "/images/categories/drones.jpg" },
        { id: 4, name: "Sale", imageUrl: "/images/categories/sale.jpg" },
        { id: 5, name: "Tablets", imageUrl: "/images/categories/tablets.jpg" },
        { id: 6, name: "Best Sellers", imageUrl: "/images/categories/bestsellers.jpg" },
        { id: 7, name: "TV & Home Cinema", imageUrl: "/images/categories/tv.jpg" },
        { id: 8, name: "Wearable Tech", imageUrl: "/images/categories/wearable.jpg" },
        { id: 9, name: "Speakers", imageUrl: "/images/categories/speakers.jpg" },
        { id: 10, name: "Headphones", imageUrl: "/images/categories/headphones.jpg" }
    ];

    useEffect(() => {
        const fetchData = async () => {
            try {
                let allProducts = [];
                const queryparams = new URLSearchParams(location.search);
                const searchItem = queryparams.get('search');

                if (searchItem) {
                    const response = await ApiService.searchProducts(searchItem);
                    allProducts = response.productList || [];
                } else {
                    const response = await ApiService.getAllProducts();
                    allProducts = response.productList || [];
                }

                setTotalPages(Math.ceil(allProducts.length / itemsPerPage));
                setProducts(allProducts.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage));

                const featured = allProducts
                    .sort((a, b) => b.rating - a.rating)
                    .slice(0, 4);
                setFeaturedProducts(featured);

            } catch (error) {
                setError(error.response?.data?.message || error.message || 'Unable to fetch products');
            }
        };

        fetchData();
    }, [location.search, currentPage]);

    return (
        <div className="home-page">
            {/* Hero Section */}
            <section className="hero-section">
                <div className="hero-image">
                    <img src="/HomePage.png" alt="Electronics Collection" />
                </div>
            </section>

            {/* Categories Section */}
            <section className="categories-section">
                <h2 className="section-title">Shop By Category</h2>
                <div className="category-grid">
                    {categories.map((category) => (
                        <div className="category-card" key={category.id}>
                            <img src={category.imageUrl} alt={category.name} />
                            <h3>{category.name}</h3>
                            <Link to={`/category/${category.id}`}>
                                Explore <FaArrowRight />
                            </Link>
                        </div>
                    ))}
                </div>
            </section>

            {/* Featured Products */}
            <section className="featured-section">
                <h2 className="section-title">Featured Products</h2>
                <div className="featured-grid">
                    {featuredProducts.map((product) => (
                        <div className="featured-card" key={product.id}>
                            <img src={product.imageUrl} alt={product.name} />
                            <h3>{product.name}</h3>
                            <p>${product.price.toFixed(2)}</p>
                            <button className="add-to-cart">
                                <FaShoppingBag /> Add to Cart
                            </button>
                        </div>
                    ))}
                </div>
            </section>

            {/* All Products Section */}
            <section className="products-section">
                <h2 className="section-title">Our Products</h2>
                {error ? (
                    <p className="error-message">{error}</p>
                ) : (
                    <>
                        <ProductList products={products} />
                        <Pagination
                            currentPage={currentPage}
                            totalPages={totalPages}
                            onPageChange={(page) => setCurrentPage(page)}
                        />
                    </>
                )}
            </section>
        </div>
    );
};

export default Home;
